CREATE TABLE `professional_services` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`professional_id` BIGINT UNSIGNED NOT NULL,`service_id` BIGINT UNSIGNED NOT NULL,`price_cents` BIGINT UNSIGNED NULL,`duration_minutes` SMALLINT UNSIGNED NULL,`has_post_service_break` BOOLEAN NULL,`post_service_break_minutes` SMALLINT UNSIGNED NULL,`active` BOOLEAN NOT NULL DEFAULT TRUE,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `professional_services_public_id_key` (`public_id`),UNIQUE INDEX `professional_services_professional_id_service_id_key` (`professional_id`,`service_id`),INDEX `professional_services_tenant_id_professional_id_active_idx` (`tenant_id`,`professional_id`,`active`),INDEX `professional_services_tenant_id_service_id_active_idx` (`tenant_id`,`service_id`,`active`),CONSTRAINT `professional_services_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `professional_services_professional_id_fkey` FOREIGN KEY (`professional_id`) REFERENCES `professionals`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `professional_services_service_id_fkey` FOREIGN KEY (`service_id`) REFERENCES `services`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
